values ('dialog_fq_omni_068', 'fq_omni_068', 'npc_director_vey', 'greeting', '[{"id": "greeting", "text": "OmniCorp''s projections indicate a resource gap requiring intervention. Rift Stalkers have established a peer-to-peer network in the Core", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The other factions play politics. OmniCorp plays percentages. We''ve identified a gap impacting quarterly projections. You''re the asset closing that gap.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Tasking: Defeat 6x Aethel Rift Stalker; Collect 1x Confirm network disconnected.\n\nReport completion via standard channels.\n\nRewards: 6400 EXP · 3200 Currency · 1600 CRD · 2100 Reputation · Dark Energy Fragment", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 496)
