values ('dialog_fq_omni_070', 'fq_omni_070', 'npc_director_vey', 'greeting', '[{"id": "greeting", "text": "Asset, your metrics have been reviewed. Gravity Recalibration — GRAVITY RECALIBRATION OPERATION", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "OmniCorp doesn''t waste resources on sentiment. Every operation is calculated for maximum return. This one is flagged high-yield — your compensation reflects that.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 1x Gravity Titan; Defeat 5x Aethel Abyssal Reaver; Collect 1x Confirm algorithm download.\n\nCompletion: immediate. Compensation: per contract.\n\nRewards: 20000 EXP · 10000 Currency · 5000 CRD · 7000 Reputation · Titan Core + Gravity Well Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 498)
