values ('dialog_fq_omni_084', 'fq_omni_084', 'npc_director_vey', 'greeting', '[{"id": "greeting", "text": "Cleared for your next assignment. The Apex Ashen Drake is a legacy biological process", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Every credit invested in you has returned positive value. That is a data point, not a compliment. Based on that data, we''re increasing your operational scope.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 1x Ashen Drake; Collect 1x Verify deletion.\n\nCompletion: immediate. Compensation: per contract.\n\nRewards: 12000 EXP · 6000 Currency · 3000 CRD · 4000 Reputation · Drake Heart + Ancient Scale", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 512)
