values ('dialog_fq_omni_100', 'fq_omni_100', 'npc_director_vey', 'greeting', '[{"id": "greeting", "text": "Cleared for your next assignment. SYSTEM STATUS: SINGULARITY ACHIEVED", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The other factions play politics. OmniCorp plays percentages. We''ve identified a gap impacting quarterly projections. You''re the asset closing that gap.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Travel to THE_SPIRE; Speak with npc_omnicorp_executive\n\nCompletion: immediate. Compensation: per contract.\n\nRewards: 50000 EXP · 25000 Currency · 12500 CRD · 10000 Reputation · Resonanted Astral Phase Crystal + Singularity Seal", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 528)
