values ('dialog_fq_shard_001', 'fq_shard_001', 'npc_elder_malakor', 'greeting', '[{"id": "greeting", "text": "Peace be with you, Child. The Glowvine has been restless. Elder Malakor''s voice carries the weight of someone who has heard the Shard...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Shard is not a weapon — it is a living memory of everything before the Severance. Billions of souls, a civilization, compressed into fragments. Shard-touched creatures are echoes.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your path, Child: Defeat 5x Glowvine Sprite; Collect 2x glowvine_seed\n\nWalk in the Shard''s light.\n\nRewards: 50 EXP · 30 Currency · 30 Reputation · Con Small Hp Cell", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 529)
