values ('dialog_fq_shard_007', 'fq_shard_007', 'npc_elder_malakor', 'greeting', '[{"id": "greeting", "text": "Come, Child of the Shard. Victims of Other Factions'' Greed — The Jungle Stalkers in the Shardroot Swamp were pushed here when OmniCorp''s...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Other factions see the forest''s creatures as threats. They don''t understand. Every Shard-touched being was once a guardian. The Severance twisted their purpose — not erased it. We release them.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 5x Jungle Stalker; Collect 1x stalker_fang\n\nThe Shard''s blessing goes with you, Child.\n\nRewards: 120 EXP · 70 Currency · 70 Reputation · Animal Fang", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 535)
