values ('dialog_fq_shard_016', 'fq_shard_016', 'npc_elder_malakor', 'greeting', '[{"id": "greeting", "text": "Come, Child of the Shard. The Shard''s Blessing and the Trial''s Weight — The Shrine Guardians do not distinguish between devotion and capability", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Other factions see the forest''s creatures as threats. They don''t understand. Every Shard-touched being was once a guardian. The Severance twisted their purpose — not erased it. We release them.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your path, Child: Defeat 3x Shrine Guardian; Collect 1x aethel_core_shard\n\nWalk in the Shard''s light.\n\nRewards: 520 EXP · 290 Currency · 310 Reputation · Aethel Core Shard", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 544)
