values ('dialog_fq_shard_020', 'fq_shard_020', 'npc_elder_malakor', 'greeting', '[{"id": "greeting", "text": "Peace be with you, Child. The Glowvine has been restless. Elder Malakor has personally requested your return to the Sanctum", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Other factions see the forest''s creatures as threats. They don''t understand. Every Shard-touched being was once a guardian. The Severance twisted their purpose — not erased it. We release them.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your path, Child: Travel to SANCTUM; Collect 1x core_fragment\n\nWalk in the Shard''s light.\n\nRewards: 900 EXP · 500 Currency · 500 Reputation · Con Medium Mp Cell", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 548)
