values ('dialog_fq_shard_069', 'fq_shard_069', 'npc_elder_malakor', 'greeting', '[{"id": "greeting", "text": "Come, Child of the Shard. The Core''s Own Guardian Must Be Named — Deeper in the Aethel Siphon Core, something waits that Oracle Seraphel has ...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Shard is not a weapon — it is a living memory of everything before the Severance. Billions of souls, a civilization, compressed into fragments. Shard-touched creatures are echoes.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Collect 3x Materials; Defeat 1x Gigantic Jotunn\n\nThe Shard''s blessing goes with you, Child.\n\nRewards: 4000 EXP · 2000 Currency · 966 CRD · 1220 Reputation · Aethel Core Shard", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 597)
